# owner: platform
import unittest

from hourglass.rounding import round_span_labels
from hourglass.models import Span


class RoundingTests(unittest.TestCase):
    def test_rounds_to_nearest_step(self):
        self.assertEqual(
            round_span_labels([Span(9 * 60 + 4, 17 * 60 + 12)], 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_halves_round_up(self):
        self.assertEqual(
            round_span_labels([Span(8, 60)], 15),
            ["00:15-01:00 (0h 45m)"]
        )

    def test_one_label_per_span(self):
        labels = round_span_labels([Span(0, 60), Span(120, 180)], 30)
        self.assertEqual(len(labels), 2)

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45):
            with self.assertRaises(ValueError):
                round_span_labels([Span(0, 60)], step)
